                uniffiRustCallWithError(FfiException) { _status ->
                    UniffiLib.uniffi_cera_ffi_fn_constructor_ceraengine_from_bytes(
                        FfiConverterByteArray.lower(`bytes`),
                        FfiConverterTypeEngineConfig.lower(`config`),
                        _status,
                    )
                },
            )

