/**
 * @suppress
 */
public object FfiConverterTypeModalitySink : FfiConverter<ModalitySink, Long> {
    internal val handleMap = UniffiHandleMap<ModalitySink>()

    override fun lower(value: ModalitySink): Long {
        if (value is ModalitySinkImpl) {
            // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
        } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
        }
    }

    override fun lift(value: Long): ModalitySink {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ModalitySinkImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): ModalitySink = lift(buf.getLong())

    override fun allocationSize(value: ModalitySink) = 8UL

    override fun write(
        value: ModalitySink,
        buf: ByteBuffer,
    ) {
        buf.putLong(lower(value))
    }
}

