        callWithHandle {
            uniffiRustCallWithError(FfiException) { _status ->
                UniffiLib.uniffi_cera_ffi_fn_method_session_send_message(
                    it,
                    FfiConverterTypeUserMessage.lower(`message`),
                    _status,
                )
            }
        }

    /**
     * Append a multimodal message and run generation synchronously while holding
     * the session lock continuously across prefill and decode.
     */
    @Throws(FfiException::class)
    override fun `sendMessageAndGenerate`(
        `message`: UserMessage,
        `opts`: GenerateOpts,
    ): GenerateOutput =
        FfiConverterTypeGenerateOutput.lift(
            callWithHandle {
                uniffiRustCallWithError(FfiException) { _status ->
                    UniffiLib.uniffi_cera_ffi_fn_method_session_send_message_and_generate(
                        it,
                        FfiConverterTypeUserMessage.lower(`message`),
                        FfiConverterTypeGenerateOpts.lower(`opts`),
                        _status,
                    )
                }
            },
        )

    /**
     * Append a multimodal message and run streaming generation while holding
     * the session lock continuously across prefill and decode.
     */
    @Throws(FfiException::class)
    override fun `sendMessageStreaming`(
        `message`: UserMessage,
        `opts`: GenerateOpts,
        `sink`: ModalitySink,
    ): GenerateSummary =
        FfiConverterTypeGenerateSummary.lift(
            callWithHandle {
                uniffiRustCallWithError(FfiException) { _status ->
                    UniffiLib.uniffi_cera_ffi_fn_method_session_send_message_streaming(
                        it,
                        FfiConverterTypeUserMessage.lower(`message`),
                        FfiConverterTypeGenerateOpts.lower(`opts`),
                        FfiConverterTypeModalitySink.lower(`sink`),
                        _status,
                    )
                }
            },
        )

    /**
     * Set a session-default cap on the longest side of an appended
     * image, in pixels (`None` = no cap). Unlike the per-call
     * `max_long_size` argument to [`Self::append_image`], this default
     * is honored by every image-append path the session drives —
     * including chat-template flows — so a host can configure the
     * image-encode budget once. See [`Self::append_image`] for the cap
     * semantics (shrinks the encoded target, never upscales, takes
     * precedence over the model's minimum-resolution floor).
     */
    @Throws(FfiException::class)
    override fun `setImageMaxLongSize`(`maxLongSize`: kotlin.UInt?) =
        callWithHandle {
            uniffiRustCallWithError(FfiException) { _status ->
                UniffiLib.uniffi_cera_ffi_fn_method_session_set_image_max_long_size(
                    it,
                    FfiConverterOptionalUInt.lower(`maxLongSize`),
                    _status,
                )
            }
        }

    /**
     * @suppress
     */
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSession : FfiConverter<Session, Long> {
    override fun lower(value: Session): Long = value.uniffiCloneHandle()

    override fun lift(value: Long): Session = Session(UniffiWithHandle, value)

    override fun read(buf: ByteBuffer): Session = lift(buf.getLong())

    override fun allocationSize(value: Session) = 8UL

    override fun write(
        value: Session,
